  const out = [];
  function walk(dir, rel) {
    let ents;
    try { ents = fsW.readdirSync(dir, { withFileTypes: true }); } catch (e) { return; }
    ents.forEach(function (ent) {
      const name = ent.name;
      if (!name || name === '.' || name === '..') return;
      const nextRel = rel ? rel + '/' + name : name;
      const abs = pathW.join(dir, name);
      if (ent.isDirectory()) return walk(abs, nextRel);
      if (!/\.pdf$/i.test(name) || name.charAt(0) === '_') return;
      let st;
      try { st = fsW.statSync(abs); } catch (e2) { return; }
      if (!st.size) return;
      const parts = nextRel.replace(/\\/g, '/').split('/');
      const channel = /^booking/i.test(parts[0] || '') ? 'booking' : 'airbnb';
      const aptName = parts.length >= 4 ? parts[2] : '';
      const leaf = parts[parts.length - 1] || name;
      out.push({
        path: abs, filename: nextRel.replace(/\\/g, '/'), channel: channel,
        kind: /credit/i.test(leaf) ? 'credit_note' : 'invoice', scope: 'leased',
        partner: aptName, aptName: aptName, bytes: st.size
      });
    });
  }
  if (outDir) walk(outDir, '');
  return out;
}
